from pathlib import Path
import json,re
root=Path.cwd();projects=json.loads((root/'scripts/projects.json').read_text(encoding='utf-8'))
css='''
/* Hình thức theo ngữ cảnh sử dụng, không dùng motion khi cuộn. */
body{--line:#d8d8d0}header{position:relative}.nav{max-width:1400px}.brand{letter-spacing:1px}.hero{gap:40px}.hero img{border-radius:0!important}.eyebrow{letter-spacing:1.4px}h1{font-weight:700}.utility-head h1{font-size:40px;letter-spacing:-1.3px;margin:8px 0}.utility-head p{margin-top:12px}.utility-head{border-bottom:1px solid var(--line);padding-bottom:20px}.utility-head .eyebrow{display:block}main:has(.utility-head){max-width:1080px}.shop .hero{position:relative;min-height:530px;grid-template-columns: .85fr 1.15fr}.shop .hero img{height:530px}.shop .hero h1{font-size:clamp(38px,4.7vw,64px)}.hero-copy{padding:24px 0}.hero .caption{display:none}.topline{font-size:12px;background:var(--accent);color:white;text-align:center;padding:8px 18px;letter-spacing:.4px}.quick-nav{display:flex;gap:10px;flex-wrap:wrap;border-block:1px solid var(--line);padding:18px 0;margin-bottom:35px}.quick-nav a{border:1px solid var(--line);padding:7px 16px;text-decoration:none;font-size:14px;background:white}.fact-strip{display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid var(--line);margin:30px 0 50px}.fact-strip div{padding:20px;border-right:1px solid var(--line)}.fact-strip strong{display:block;font-size:15px}.fact-strip p{font-size:13px;margin:4px 0 0;color:#62695e}.feature-note{display:grid;grid-template-columns:1fr 1fr;gap:45px;align-items:center;margin:60px 0;border-top:1px solid var(--line);padding-top:35px}.feature-note img{width:100%;height:300px;object-fit:cover}.feature-note h2{font-size:36px}.item img{height:255px}.shop .item img{height:300px}.item small{display:block;padding-top:8px;font-size:11px;letter-spacing:1px}.item h3{font-weight:600}.shop .item button{background:transparent;color:var(--accent)}.catalog-title{font-size:44px}.shop .grid{gap:38px 26px}.editorial-hero{position:relative;min-height:560px;display:flex;align-items:flex-end;margin:0 0 40px}.editorial-hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0}.editorial-hero::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#10241de0,transparent 95%)}.editorial-hero>div{position:relative;z-index:1;padding:45px;color:white;max-width:760px}.editorial-hero .eyebrow{color:#fff}.editorial-hero h1{max-width:690px;font-weight:650}.editorial-hero .button{background:#fff;color:#203c32;border-color:white}.editorial-hero p{max-width:490px}.booking .hero img{height:500px}.booking .item,.stay .item,.ticket .item{background:#fff;border:1px solid var(--line);padding:0 0 20px}.booking .item>:not(img),.stay .item>:not(img),.ticket .item>:not(img){margin-left:20px;margin-right:20px}.ticket{--paper:#f0ede7!important}.ticket .hero{grid-template-columns:1.1fr .9fr}.ticket .hero h1{font-size:70px}.ticket .hero img{height:420px}.ticket .item img{height:280px}.course .hero{background:#e5ece6;padding:40px;margin-top:0}.course .hero h1{font-size:52px}.course .hero img{height:340px}.course .item{background:white;padding:20px;border:1px solid var(--line)}.course .item img{height:170px}.blog .hero{grid-template-columns:1.1fr .9fr}.blog .hero h1{font-size:60px}.blog .item{display:grid;grid-template-columns:130px 1fr;gap:0 20px;padding:22px 0}.blog .item img{grid-row:1/6;height:150px}.blog .item small{padding:0}.blog .grid{grid-template-columns:1fr 1fr}.gallery .hero{grid-template-columns:1fr 1.4fr}.gallery .hero img{height:480px}.gallery .item{border:none}.gallery .item h3{font-size:16px}.gallery .item img{height:380px}.side-intro{display:grid;grid-template-columns:250px 1fr;gap:40px}.side-intro aside{border-right:1px solid var(--line);padding-right:20px}.guide .grid{gap:30px}.sectionhead h2{font-size:25px}.row{background:white;padding:16px}.stats{border-bottom:1px solid var(--line);margin-bottom:20px}.stats .stat{font-size:26px}#task-list{margin-top:20px}#quiz-box{max-width:780px}.choices button{min-height:55px}.calendar .day{min-height:70px}.today{font-weight:700}.account-link{font-weight:600}.detail-specs{border-top:1px solid var(--line);padding-top:12px}.detail-specs dl{display:grid;grid-template-columns:140px 1fr;gap:8px}.detail-specs dd{margin:0}.detail-specs dt{color:#62695e}.shop .toolbar{padding:20px;background:#edece6}.tools .panel,.expense .panel{margin-top:20px}.tech .hero h1{font-size:58px}.project-index{padding:40px 0}.project-index a{display:flex;align-items:center;gap:20px;padding:16px 0;border-bottom:1px solid #ccc;text-decoration:none}.project-index b{min-width:180px}.project-index span{font-size:14px;color:#62695e}
@media(max-width:850px){.shop .hero,.course .hero,.ticket .hero,.blog .hero,.gallery .hero{grid-template-columns:1fr}.shop .hero img{height:380px}.fact-strip{grid-template-columns:1fr}.fact-strip div{border-bottom:1px solid var(--line)}.feature-note,.side-intro{grid-template-columns:1fr;gap:20px}.side-intro aside{border-right:0}.blog .grid{grid-template-columns:1fr}.course .hero{padding:24px}.editorial-hero{min-height:500px}.editorial-hero>div{padding:28px}.ticket .hero h1,.blog .hero h1{font-size:48px}}@media(max-width:520px){.shop .hero img{height:340px}.shop .hero{min-height:0}.editorial-hero{min-height:510px}.editorial-hero h1{font-size:40px}.hero h1,.course .hero h1{font-size:38px}.hero img{height:300px}.utility-head h1{font-size:34px}.blog .item{grid-template-columns:90px 1fr}.blog .item img{height:120px}.feature-note h2{font-size:28px}.gallery .item img{height:310px}.project-index a{align-items:flex-start;flex-direction:column;gap:4px}}
'''
# Specific copy and secondary story, no invented operational promises.
stories={
'fashion':('Tủ đồ bắt đầu từ những món dễ phối.','Áo sơ mi linen đi cùng quần suông, thêm túi vải cho một ngày đến lớp. Chọn theo cách bạn mặc mỗi ngày, thay vì chạy theo một bộ sưu tập quá lớn.','Chất liệu & phom dáng','Linen, cotton và vải canvas · Thông tin kích cỡ trong từng sản phẩm'),
 'tech':('Lắp một góc làm việc vừa ngân sách.','Bắt đầu với màn hình và bàn phím. Nếu máy chậm khi mở nhiều ứng dụng, xem thêm lựa chọn RAM và SSD trước khi nâng cấp toàn bộ máy.','Thông số trước, lựa chọn sau','Xem dung lượng, kết nối và khả năng tương thích trong chi tiết'),
 'furniture':('Đo góc phòng trước khi chọn đồ.','Một chiếc bàn vừa chiều ngang, một chiếc ghế vừa tầm ngồi. Kích thước và vật liệu được trình bày cùng sản phẩm để bạn dễ hình dung trong không gian của mình.','Góc làm việc nhỏ','Bàn, ghế, đèn và kệ cho căn phòng diện tích gọn'),
 'handmade':('Mỗi món đều có một chút khác biệt.','Gốm có thể lệch một vệt men, túi đan có thể khác một mắt sợi. Những chi tiết nhỏ là điều tạo nên cảm giác gần gũi của đồ thủ công.','Vật liệu tự nhiên','Gốm, cotton, mây và sáp thực vật'),
 'bookstore':('Bạn đang muốn đọc gì?','Một cuốn để học, một cuốn để nghỉ ngơi, một cuốn ghi lại chuyến đi. Tìm theo tên sách hoặc bắt đầu từ các gợi ý của hiệu sách.','Đọc thử trước khi chọn','Thông tin nội dung và quy cách trong từng đầu sách'),
 'flowers':('Một bó hoa cho đúng dịp.','Sinh nhật cần một sắc màu tươi, lời cảm ơn có thể chỉ cần một bó vừa tay. Chọn loại hoa và viết thêm lời nhắn của bạn khi lưu đơn hàng.','Hoa & lời nhắn','Sáu gợi ý từ bó hoa nhỏ đến hộp quà sinh nhật'),
 'organic':('Chọn theo bữa ăn, mua vừa đủ.','Bắt đầu từ rau cho hôm nay, thêm trái cây và một ít đồ khô cho tuần tới. Quy cách đóng gói được ghi rõ trong từng mặt hàng.','Đơn vị rõ ràng','Rau theo gói, trái cây theo kg, mật ong theo chai'),
 'dalat':('Một ngày đi từ trung tâm lên đồi.','Buổi sáng ghé ga cũ, buổi chiều dành cho hồ và những cung đường có thông. Lưu một vài điểm đến thay vì xếp kín lịch cả ngày.','Sổ tay điểm đến','Tìm điểm dừng và ghi chú cho hành trình'),
 'tours':('Chọn hành trình theo quỹ thời gian.','Hai ngày cho một chuyến ngắn, ba đến bốn ngày để đi xa hơn. Mỗi hành trình có thời lượng, chi phí tham khảo và biểu mẫu chọn ngày khởi hành.','Lên lịch chuyến đi','Xem tour, chọn ngày và số người'),
 'homestay':('Phòng nào hợp với chuyến đi của bạn?','Phòng nhỏ cho hai người hay căn nhà cho cả nhóm? Xem từng không gian, chọn ngày nhận phòng và số đêm để tính chi phí dự kiến.','Một chỗ để nghỉ','Thông tin phòng và chi phí theo đêm'),
 'cuisine':('Đi qua những miền vị.','Từ nước dùng thanh của phở đến vị cay thơm của bún bò, mỗi món ăn gắn với một cách sống và một vùng nguyên liệu.','Bản đồ món Việt','Sáu món ăn, sáu điểm bắt đầu tìm hiểu'),
 'festivals':('Hiểu câu chuyện trước khi đến hội.','Lễ hội không chỉ là một điểm tham quan. Tìm hiểu tập quán, ý nghĩa và cách tham gia phù hợp để tôn trọng không gian văn hóa địa phương.','Ghi chép văn hóa','Thông tin nền trước chuyến tham quan'),
 'tickets':('Chọn một chương trình cho tối nay.','Phim, acoustic hay một đêm jazz? Xem chương trình, chọn ngày và số vé để lưu kế hoạch đi cùng bạn bè.','Lịch giải trí','Đặt vé mô phỏng, không thanh toán'),
 'language':('Tìm lớp đúng với điểm bắt đầu.','Bạn mới học hay đã có nền tảng? Xem mục tiêu từng lớp, thử một bài học và lưu tiến độ trước khi chọn lộ trình tiếp theo.','Bắt đầu bằng bài mẫu','Sáu lớp từ cơ bản đến giao tiếp'),
 'courses':('Một lộ trình, một sản phẩm thực hành.','Bắt đầu từ cấu trúc HTML, chuyển sang bố cục CSS rồi thêm tương tác bằng JavaScript. Mỗi chặng có một bài mẫu để tự kiểm tra.','Học theo từng chặng','Mở bài học và đánh dấu hoàn thành'),
 'coding':('Hiểu nguyên lý, rồi tự làm lại.','Dựng cấu trúc bằng HTML, chia bố cục bằng CSS, xử lý thao tác bằng JavaScript. Bạn có thể bắt đầu từ phần mình chưa chắc.','Thực hành web','Bài mẫu ngắn và tiến độ lưu trên trình duyệt'),
 'study-blog':('Ghi chép để lần sau tìm lại.','Tài liệu được chia thành chủ đề nhỏ: cú pháp, bố cục, lập trình và phương pháp tự học. Mở một ghi chú, thử ví dụ rồi viết lại bằng cách của bạn.','Sổ tay học tập','Sáu chủ đề cho học phần thiết kế web'),
 'gallery':('Một album cho những điều bình thường.','Ánh sáng trên đồi, một góc phố hay chiếc bàn quen. Nhấp ảnh để xem lớn; dùng mục thêm nội dung để lưu ảnh của riêng bạn.','Bộ ảnh / Đời thường','Xem ảnh lớn, tải ảnh mới và lưu cục bộ')}
for c in projects:
 slug,name,cat,head,desc,kind,color,_,photo=c;folder=root/slug
 for p in folder.glob('*.html'):
  s=p.read_text(encoding='utf-8').replace('class="'+kind+'"','class="'+kind+' '+slug+'"')
  if kind=='shop':s=s.replace('</nav>','<a class="account-link" href="products.html#basket">Giỏ hàng</a></nav>')
  s=s.replace('Khám phá</a>',('Điểm đến' if slug=='dalat' else 'Món ăn' if slug=='cuisine' else 'Lễ hội' if slug=='festivals' else 'Đặt phòng' if kind=='stay' else 'Lịch diễn' if kind=='ticket' else 'Hành trình' if kind=='booking' else 'Album ảnh' if kind=='gallery' else 'Bài viết' if kind=='blog' else 'Dịch vụ' if kind=='appointment' else 'Công cụ')+'</a>')
  p.write_text(s,encoding='utf-8')
 # Homepage: tools open directly, no marketing detour.
 if kind in ['todo','expense','calendar','tools','quiz']:
  src=(folder/'products.html').read_text(encoding='utf-8');start=src.index('<main ');end=src.index('</main>')+7
  body=src[start:end];ws=body.index('<div id="workspace">');body='<main id="main"><div class="utility-head"><span class="eyebrow">'+name+' / '+cat+'</span><h1>'+head+'</h1><p>'+desc+'</p></div>'+body[ws:]
  home=(folder/'index.html').read_text(encoding='utf-8');home=re.sub(r'<main .*?</main>',lambda m:body,home,flags=re.S);(folder/'index.html').write_text(home,encoding='utf-8')
 else:
  story=stories.get(slug,('Chọn dịch vụ theo thời gian của bạn.','Xem thông tin từng dịch vụ, chọn ngày và khung giờ còn trống. Các cuộc hẹn được lưu để bạn theo dõi trên trình duyệt này.','Thời gian cho bản thân','Đặt lịch theo khung giờ, tránh trùng lịch'))
  s=(folder/'index.html').read_text(encoding='utf-8')
  if slug in ['dalat','cuisine','festivals','homestay']:
   s=re.sub(r'<section class="hero">.*?</section>',lambda m:f'<section class="editorial-hero"><img src="images/banner.jpg" alt="{cat}"><div><span class="eyebrow">{name} / {cat}</span><h1>{head}</h1><p>{desc}</p><a class="button" href="products.html">'+('Xem phòng trống' if slug=='homestay' else 'Mở sổ tay')+'</a></div></section>',s,flags=re.S)
  s=s.replace(' / Bộ sưu tập 01',' / '+('Trang phục hằng ngày' if slug=='fashion' else cat))
  s=s.replace('<div class="caption">'+name+' — Những lựa chọn cho nhịp sống của bạn.</div>','')
  if kind=='shop':
   cats=['Áo & quần','Giày & túi','Phụ kiện'] if slug=='fashion' else ['Tất cả sản phẩm','Gợi ý lựa chọn','Thông tin cửa hàng']
   s=s.replace('<div class="sectionhead">','<div class="quick-nav">'+''.join('<a href="products.html">'+x+'</a>' for x in cats)+'</div><div class="sectionhead">',1)
  s=s.replace('Gợi ý khám phá',{'shop':'Đang có tại cửa hàng','course':'Chọn một lộ trình','booking':'Hành trình đề xuất','stay':'Những căn phòng','ticket':'Chương trình sắp tới','blog':'Ghi chú mới','gallery':'Ảnh trong bộ sưu tập','appointment':'Chọn dịch vụ'}.get(kind,'Trong sổ tay'))
  storyhtml=f'<section class="feature-note"><img loading="lazy" src="images/product-02.jpg" alt="{story[2]}"><div><span class="eyebrow">{story[2]}</span><h2>{story[0]}</h2><p>{story[1]}</p><a href="products.html">'+('Xem các lựa chọn' if kind=='shop' else 'Tìm hiểu thêm')+'</a></div></section>'
  s=s.replace('<p id="status"',storyhtml+'<p id="status"')
  (folder/'index.html').write_text(s,encoding='utf-8')
 (folder/'css/style.css').write_text((folder/'css/style.css').read_text(encoding='utf-8')+css,encoding='utf-8')
# Retain the design layer as an explicit build step, so changes can be reviewed.
(root/'scripts/design-layer.css').write_text(css,encoding='utf-8')
